		public static IDisposable SwapRandom(string key)
		{
			if (_rngs == null)
			{
				throw new Exception("SwapRandom is only meant to be used on the Main thread");
			}
			if (!_rngs.TryGetValue(key, out var value))
			{
				value = (_rngs[key] = new UnifiedRandom(ActiveWorldFileData.Seed));
			}
			return RandomSwap.Swap(value);
		}

