		public void autoCreate(string worldSize)
		{
			switch (worldSize)
			{
			case "0":
				autoGen = false;
				break;
			case "1":
				maxTilesX = 4200;
				maxTilesY = 1200;
				autoGen = true;
				break;
			case "2":
				maxTilesX = 6400;
				maxTilesY = 1800;
				autoGen = true;
				break;
			case "3":
				maxTilesX = 8400;
				maxTilesY = 2400;
				autoGen = true;
				break;
			}
		}

