							{
								num7 = 0.0;
								Thread.Sleep(10);
							}
						}
					}
				}
				Thread.Sleep(0);
			}
			if (Netplay.SaveOnServerExit)
			{
				Console.WriteLine(Language.GetTextValue("Net.ServerSavingOnExit"));
				WorldFile.SaveWorld();
			}
			YouCanSleepNow();
		}

