		private void DoUpdate_AnimateWaterfalls()
		{
			wFrCounter += windSpeedCurrent * 2f;
			if (wFrCounter > 4f)
			{
				wFrCounter = 0f;
				wFrame += 1f;
			}
			if (wFrCounter < 0f)
			{
				wFrCounter = 4f;
				wFrame -= 1f;
			}
			if (wFrame > 16f)
			{
				wFrame = 1f;
			}
			if (wFrame < 1f)
			{
				wFrame = 16f;
			}
			waterfallManager.UpdateFrame();
		}

