			if (DiscoStyle == 1)
			{
				DiscoR -= num;
				if (DiscoR <= 0)
				{
					DiscoR = 0;
					DiscoStyle++;
				}
			}
			if (DiscoStyle == 2)
			{
				DiscoB += num;
				if (DiscoB >= 255)
				{
					DiscoB = 255;
					DiscoStyle++;
				}
			}
			if (DiscoStyle == 3)
			{
				DiscoG -= num;
				if (DiscoG <= 0)
				{
					DiscoG = 0;
					DiscoStyle++;
				}
			}
			if (DiscoStyle == 4)
			{
				DiscoR += num;
				if (DiscoR >= 255)
				{
					DiscoR = 255;
					DiscoStyle++;
				}
			}
			if (DiscoStyle == 5)
			{
				DiscoB -= num;
				if (DiscoB <= 0)
