			case 117:
				newColor.X *= 1.1f;
				newColor.Z *= 1.2f;
				break;
			case 204:
				num = 0.3f + (float)(int)mouseTextColor / 300f;
				newColor.X *= 1.3f * num;
				break;
			case 211:
				num = 0.3f + (float)(int)mouseTextColor / 300f;
				newColor.Y *= 1.5f * num;
				newColor.Z *= 1.1f * num;
				break;
