				newColor.Z *= 1.15f;
				break;
			case 163:
				newColor.X *= 1.05f;
				newColor.Y *= 1.1f;
				newColor.Z *= 1.15f;
				break;
			case 164:
				newColor.X *= 1.1f;
				newColor.Y *= 1.1f;
				newColor.Z *= 1.2f;
				break;
			case 178:
				num = 0.5f;
				newColor.X *= 1f + num;
				newColor.Y *= 1f + num;
				newColor.Z *= 1f + num;
				break;
			case 185:
			case 186:
				num = 0.3f;
