		protected void DrawNPC(NPC npc, bool behindTiles)
		{
			Vector2 screenPos = screenPosition;
			DrawNPCDirect(spriteBatch, npc, behindTiles, screenPos);
			if (npc.netOffset != Vector2.Zero && DebugOptions.ShowNetOffset)
			{
				npc.position -= npc.netOffset;
				DebugVisualizer.World.AddRectangle(npc.Hitbox, Microsoft.Xna.Framework.Color.YellowGreen, 1, 2f);
				DebugVisualizer.World.AddLine(npc.Center + npc.netOffset, npc.Center, Microsoft.Xna.Framework.Color.Red, Microsoft.Xna.Framework.Color.YellowGreen, 1, 2f);
				npc.position += npc.netOffset;
			}
		}

		public void DrawNPCDirect_QueenSlimeWings(NPC rCurrentNPC, SpriteBatch mySpriteBatch, Vector2 screenPos, Vector2 drawCenter, Microsoft.Xna.Framework.Color originColor)
