			if (hitbox.Width < num)
			{
				hitbox.Inflate((num - hitbox.Width) / 2, 0);
			}
			if (hitbox.Height < num)
			{
				hitbox.Inflate(0, (num - hitbox.Height) / 2);
			}
			bool flag = hitbox.Contains(v.ToPoint());
			bool num2 = (flag || SmartInteractProj == proj.whoAmI) & !localPlayer.lastMouseInterface;
			bool flag2 = !SmartCursorIsUsed && !PlayerInput.UsingGamepad;
			if (!num2)
			{
				if (!flag2)
				{
					return 1;
				}
				return 0;
			}
			HasInteractableObjectThatIsNotATile = true;
			if (flag)
			{
				localPlayer.noThrow = 4;
				localPlayer.cursorItemIconEnabled = true;
				localPlayer.cursorItemIconID = itemIcon;
			}
			if (PlayerInput.UsingGamepad)
			{
				localPlayer.GamepadEnableGrappleCooldown();
			}
			if (mouseRight && mouseRightRelease && Player.BlockInteractionWithProjectiles == 0)
			{
				mouseRightRelease = false;
				localPlayer.tileInteractAttempted = true;
				localPlayer.tileInteractionHappened = true;
				localPlayer.releaseUseTile = false;
				bool giveItem = true;
				TryDespawningProjectile_ModifyBeforeKill(proj, ref giveItem);
				proj.Kill();
				if (giveItem && ProjectileID.Sets.DespawnItemGivesItemBack[proj.type])
				{
					Item.RequestNewItem(proj.GetItemSource_DropAsItem(), proj.Center, itemIcon, 1, 0, NewItemOwnership.ReserveForLocalPlayer);
				}
				TryDespawningProjectile_SpecialkillCode(proj);
			}
			if (!SmartCursorIsUsed && !PlayerInput.UsingGamepad)
			{
				return 0;
			}
			if (!flag2)
			{
				return 2;
			}
			return 0;
		}

		private void TryDespawningProjectile_ModifyBeforeKill(Projectile proj, ref bool giveItem)
		{
			if (proj.aiStyle == 16 && !proj.hostile)
			{
				proj.ai[0] = 1000f;
				NetMessage.SendData(27, -1, -1, null, proj.whoAmI);
			}
		}

		private void TryDespawningProjectile_SpecialkillCode(Projectile proj)
		{
			if (proj.type != 250 && proj.type != 251)
			{
				return;
			}
			for (int i = 0; i < 1000; i++)
			{
				Projectile projectile = Main.projectile[i];
				if (projectile.active && projectile.owner == proj.owner && (projectile.type == 250 || projectile.type == 251))
				{
					projectile.Kill();
				}
			}
		}

		private static int TryPetting(Projectile proj, int itemIcon)
		{
			if (gamePaused || gameMenu)
			{
				return 0;
			}
			Player localPlayer = LocalPlayer;
			if (!localPlayer.IsProjectileInteractableAndInInteractionRange(proj, localPlayer.Center))
			{
				return 0;
			}
			Vector2 v = ReverseGravitySupport(MouseScreen) + screenPosition;
			Microsoft.Xna.Framework.Rectangle hitbox = proj.Hitbox;
			if (proj.type == 1094 || proj.type == 1113)
			{
				hitbox.Inflate(6, 6);
			}
			bool flag = hitbox.Contains(v.ToPoint());
			bool num = (flag || SmartInteractProj == proj.whoAmI) & !localPlayer.lastMouseInterface;
			bool flag2 = !SmartCursorIsUsed && !PlayerInput.UsingGamepad;
			if (!num)
			{
				if (!flag2)
				{
					return 1;
				}
				return 0;
			}
			HasInteractableObjectThatIsNotATile = true;
			if (flag)
			{
				localPlayer.noThrow = 4;
				localPlayer.cursorItemIconEnabled = true;
				localPlayer.cursorItemIconID = itemIcon;
			}
			if (PlayerInput.UsingGamepad)
			{
				localPlayer.GamepadEnableGrappleCooldown();
			}
			if (mouseRight && mouseRightRelease && Player.BlockInteractionWithProjectiles == 0)
			{
				mouseRightRelease = false;
				localPlayer.tileInteractAttempted = true;
				localPlayer.tileInteractionHappened = true;
				localPlayer.releaseUseTile = false;
				localPlayer.PetAnimal(proj.GetPettingInfo(localPlayer));
			}
			if (!SmartCursorIsUsed && !PlayerInput.UsingGamepad)
			{
				return 0;
			}
			if (!flag2)
			{
				return 2;
			}
			return 0;
		}

