			{
				Rain rain = Main.rain[i];
				if (rain.active)
				{
					value.X = rain.type * 4;
					Microsoft.Xna.Framework.Color color = Lighting.GetColor((int)(rain.position.X + 4f) >> 4, (int)(rain.position.Y + 4f) >> 4) * 0.85f;
					if (shimmerAlpha > 0f)
