					if (mouseLeft && mouseLeftRelease)
					{
						array[hoveredSnippet].OnClick();
					}
				}
			}
			chatMonitor.DrawChat(drawingPlayerChat);
			TimeLogger.PlayerChat.AddTime(fromTimestamp);
		}

