		public static void DrawProjectileHitbox(Projectile proj)
		{
			CollisionVisualizer.enabled = true;
			Microsoft.Xna.Framework.Rectangle targetRect = Utils.CenteredRectangle(MouseWorld, new Vector2(10f, 10f));
			if (proj.hostile && proj.friendly)
			{
				CollisionVisualizer.colorSelf = OurFavoriteColor;
			}
			else if (proj.hostile)
			{
				CollisionVisualizer.colorSelf = Microsoft.Xna.Framework.Color.Red;
			}
			else if (proj.damage > 0)
			{
				CollisionVisualizer.colorSelf = Microsoft.Xna.Framework.Color.LimeGreen;
			}
			else
			{
				CollisionVisualizer.colorSelf = Microsoft.Xna.Framework.Color.Teal;
			}
			CollisionVisualizer.colorSelf *= 0.5f;
			proj.Colliding(proj.Damage_GetHitbox(), targetRect);
			CollisionVisualizer.enabled = false;
		}

		public void DrawProjectileHitboxes()
		{
			if (!DebugOptions.DrawHitboxes)
			{
				return;
			}
			CollisionVisualizer.enabled = true;
			Microsoft.Xna.Framework.Rectangle hitbox = LocalPlayer.Hitbox;
			for (int i = 0; i < maxNPCs; i++)
			{
				NPC nPC = npc[i];
				if (nPC.active)
				{
					if (!nPC.dontTakeDamage && !nPC.friendly && (nPC.aiStyle != 112 || nPC.ai[2] <= 1f) && LocalPlayer.CanNPCBeHitByPlayerOrPlayerProjectile(nPC))
					{
						CollisionVisualizer.colorSelf = Microsoft.Xna.Framework.Color.Orange;
					}
					else
					{
						CollisionVisualizer.colorSelf = Microsoft.Xna.Framework.Color.Cyan;
					}
					CollisionVisualizer.colorSelf *= 0.5f;
					Microsoft.Xna.Framework.Rectangle npcRect = nPC.getRect();
					int specialHitSetter = 1;
					float damageMultiplier = 1f;
					NPC.GetMeleeCollisionData(hitbox, i, ref specialHitSetter, ref damageMultiplier, ref npcRect);
					CollisionVisualizer.VisualizeRects(npcRect, hitbox, needsCanHitCheck: false);
				}
			}
			for (int j = 0; j < 255; j++)
			{
				Player player = Main.player[j];
				if (player.active && !player.dead)
				{
					CollisionVisualizer.colorSelf = Microsoft.Xna.Framework.Color.Blue;
					CollisionVisualizer.colorSelf *= 0.5f;
					CollisionVisualizer.VisualizeRects(player.Hitbox, hitbox, needsCanHitCheck: false);
					Item heldItem = player.HeldItem;
					if (((heldItem.damage >= 0 && heldItem.type > 0 && !heldItem.noMelee) || heldItem.type == 1991 || heldItem.type == 3183 || heldItem.type == 4821) && player.itemAnimation > 0)
					{
						Microsoft.Xna.Framework.Rectangle heldItemFrame = player.AnimatePlayerAndGetItemFrame(player.HeightOffsetHitboxCenter, heldItem);
						player.ItemCheck_GetMeleeHitbox(heldItem, heldItemFrame, out var _, out var itemRectangle);
						CollisionVisualizer.colorSelf = Microsoft.Xna.Framework.Color.LimeGreen;
						CollisionVisualizer.colorSelf *= 0.5f;
						CollisionVisualizer.VisualizeRects(itemRectangle, hitbox, needsCanHitCheck: false);
					}
				}
			}
			CollisionVisualizer.enabled = false;
		}

		public void DrawNPCAggro()
		{
			if (!DebugOptions.DrawAggro)
			{
				return;
			}
			_ = Microsoft.Xna.Framework.Color.Red;
			Microsoft.Xna.Framework.Color ourFavoriteColor = OurFavoriteColor;
			for (int i = 0; i < maxNPCs; i++)
			{
				NPC nPC = npc[i];
				if (!nPC.active || nPC.type == 488 || nPC.Distance(LocalPlayer.Center) > 3000f)
				{
					continue;
				}
				Microsoft.Xna.Framework.Color red = Microsoft.Xna.Framework.Color.Red;
				float amount = Utils.Remap(nPC.targetSetFrame, EverLastingTicker - 60, EverLastingTicker, 1f, 0f);
				if (nPC.target < 0 || nPC.target >= 255)
				{
					Microsoft.Xna.Framework.Color color = Microsoft.Xna.Framework.Color.Lerp(ourFavoriteColor, red, amount) * 0.75f;
					Utils.DrawLine(spriteBatch, nPC.Center + new Vector2(-8f, -8f), nPC.Center + new Vector2(8f, 8f), color, color, 4f);
					Utils.DrawLine(spriteBatch, nPC.Center + new Vector2(-8f, 8f), nPC.Center + new Vector2(8f, -8f), color, color, 4f);
					continue;
				}
				red = ((nPC.dontTakeDamage || nPC.friendly || (nPC.aiStyle == 112 && !(nPC.ai[2] <= 1f)) || !LocalPlayer.CanNPCBeHitByPlayerOrPlayerProjectile(nPC)) ? Microsoft.Xna.Framework.Color.LimeGreen : Microsoft.Xna.Framework.Color.Red);
				Vector2 center = nPC.Center;
				Player player = Main.player[nPC.target];
				if (player.dead)
				{
					red = Microsoft.Xna.Framework.Color.Lerp(red, Microsoft.Xna.Framework.Color.Black, 0.5f);
				}
				int num = ((nPC.realLife != -1) ? 50 : 150);
				Vector2 end = center.MoveTowards(player.MountedCenter, num);
				float num2 = MathHelper.Lerp(20f, 4f, amount);
				Utils.DrawLine(spriteBatch, center, end, Microsoft.Xna.Framework.Color.Black, Microsoft.Xna.Framework.Color.Transparent, num2 + 4f);
				Utils.DrawLine(spriteBatch, center, end, Microsoft.Xna.Framework.Color.Lerp(ourFavoriteColor, red, amount), Microsoft.Xna.Framework.Color.Transparent, num2);
			}
		}

		private void DrawPaladinsShield()
		{
			Player localPlayer = LocalPlayer;
			if (localPlayer.dead)
			{
				return;
			}
			if (localPlayer.hasPaladinShield)
			{
				for (int i = 0; i < 255; i++)
				{
					if (i != myPlayer)
					{
						Player player = Main.player[i];
						if (player.active && !player.dead && localPlayer.CanDefendWithPaladinsShield(player.team))
						{
							DrawPaladinsShieldBoundary(localPlayer.MountedCenter, player.MountedCenter);
						}
					}
				}
			}
			if (!localPlayer.defendedByPaladin)
			{
				return;
			}
			for (int j = 0; j < 255; j++)
			{
				if (j != myPlayer)
				{
					Player player2 = Main.player[j];
					if (player2.CanDefendWithPaladinsShield(localPlayer.team))
					{
						DrawPaladinsShieldBoundary(player2.MountedCenter, localPlayer.MountedCenter);
					}
				}
			}
		}

