			case 235:
				num = (int)(GetBackgroundCounter() / 20) % 4;
				rectangle = TextureAssets.Background[backgroundTextureIndex].Frame(2, 2, num % 2, num / 2);
				rectangle.Inflate(0, -2);
				return rectangle;
			case 219:
			case 220:
			case 221:
			case 271:
			case 272:
			case 273:
			case 302:
			case 303:
			case 305:
			case 307:
			case 309:
			case 311:
			case 313:
			case 315:
			case 317:
			case 326:
			case 337:
			case 338:
			case 341:
				num = (int)(GetBackgroundCounter() / 15) % 4;
				rectangle = TextureAssets.Background[backgroundTextureIndex].Frame(2, 2, num % 2, num / 2);
				rectangle.Inflate(0, -2);
				return rectangle;
			case 281:
